// 匹配算法：core 0.30 + exec 0.22 + scene 0.16 + impact 0.10 + age 0.07 + culture 0.05 + novelty 0.05 + opt-in identity 0.03 + editorial 0.02
export function matchStoryMirrorPeople(
  userSignature: {
    qm_core: {
      inattention_mean: number;
      hyperactivity_mean: number;
      impulsivity_mean: number;
    };
    executive_function: Record<string, number>;
    functional_impact: Record<string, number>;
    primary_scenes?: string[];
    age_group?: string;
    culture?: string;
    opt_in_identity?: string[];
  },
  options: {
    count?: number;
    useIdentityAffinity?: boolean;
    disclosureClassFilter?: string[];
  } = {}
): StoryMirrorPerson[] {
  const { count = 3, useIdentityAffinity = false, disclosureClassFilter } = options;

  const candidates = STORY_MIRROR_PEOPLE.filter((p) => {
    if (disclosureClassFilter && !disclosureClassFilter.includes(p.disclosure_class)) return false;
    // 只返回 public_ready 的，source_review_required 的需要项目方审核后才能上线
    return p.review_status === 'public_ready';
  });

  const scored = candidates.map((person) => {
    let score = 0;

    // 0.30 - 核心症状相似度
    const coreScore = calculateCoreSimilarity(userSignature.qm_core, person.symptom_context_tags);
    score += coreScore * 0.30;

    // 0.22 - 执行功能相似度
    const execScore = calculateExecSimilarity(userSignature.executive_function, person.executive_function_tags);
    score += execScore * 0.22;

    // 0.16 - 场景相似度
    const sceneScore = calculateSceneSimilarity(userSignature.primary_scenes || [], person.impairment_context_tags);
    score += sceneScore * 0.16;

    // 0.10 - 功能影响相似度
    const impactScore = calculateImpactSimilarity(userSignature.functional_impact, person.impairment_context_tags);
    score += impactScore * 0.10;

    // 0.07 - 年龄/人生阶段
    const ageScore = person.age_generation === userSignature.age_group ? 1 : 0.3;
    score += ageScore * 0.07;

    // 0.05 - 文化/语言
    const cultureScore = person.culture_region === userSignature.culture ? 1 : 0.3;
    score += cultureScore * 0.05;

    // 0.05 - 新颖性（基础分，实际应基于曝光历史）
    score += 0.5 * 0.05;

    // 0.03 - 身份亲近感（仅 opt-in）
    if (useIdentityAffinity && userSignature.opt_in_identity) {
      const hasIdentityOverlap = userSignature.opt_in_identity.some((id) =>
        person.identity_bucket.includes(id)
      );
      score += (hasIdentityOverlap ? 1 : 0) * 0.03;
    }

    // 0.02 - 编辑质量
    score += (person.review_status === 'public_ready' ? 1 : 0.5) * 0.02;

    return { person, score };
  });

  scored.sort((a, b) => b.score - a.score);

  return scored.slice(0, count).map((s) => s.person);
}

function calculateCoreSimilarity(core: any, tags: string[]): number {
  let match = 0;
  let total = 0;
  if (core.inattention_mean >= 2) { match += tags.includes('inattention') ? 1 : 0; total++; }
  if (core.hyperactivity_mean >= 2) { match += tags.includes('hyperactivity') ? 1 : 0; total++; }
  if (core.impulsivity_mean >= 2) { match += tags.includes('impulsivity') ? 1 : 0; total++; }
  return total > 0 ? match / total : 0.3;
}

function calculateExecSimilarity(execFn: Record<string, number>, tags: string[]): number {
  const topEfs = Object.entries(execFn)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([k]) => k);
  const matches = topEfs.filter((ef) => tags.includes(ef)).length;
  return topEfs.length > 0 ? matches / topEfs.length : 0.3;
}

function calculateSceneSimilarity(scenes: string[], tags: string[]): number {
  if (scenes.length === 0) return 0.3;
  const matches = scenes.filter((s) => tags.some((t) => t.includes(s))).length;
  return scenes.length > 0 ? Math.min(1, matches / scenes.length) : 0.3;
}

function calculateImpactSimilarity(impact: Record<string, number>, tags: string[]): number {
  const highImpact = Object.entries(impact)
    .filter(([k, v]) => v >= 2.5)
    .map(([k]) => k);
  if (highImpact.length === 0) return 0.3;
  const matches = highImpact.filter((d) => tags.some((t) => t.includes(d))).length;
  return Math.min(1, matches / highImpact.length);
}

export const STORY_MIRROR_PEOPLE_COUNT = STORY_MIRROR_PEOPLE.length;
